function [total] = sensor_power(mode, p)
%SENSOR_POWER  The power of the sensors in flight mode `mode` [W], from each sensor's whole steady power p (every unit of the fill
%   line, in the order of Sensor: 0 where the product fits none), summed from zero in that order.
%   mode: int (passed a whole number)
%   p: real[1][7] (passed a plain number)
%   returns total: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    total = 0;
    total = 0;
    if asils.models.sensorpower.sensor_on(mode, 0)
        total = (total + p(1));
    end
    if asils.models.sensorpower.sensor_on(mode, 1)
        total = (total + p(2));
    end
    if asils.models.sensorpower.sensor_on(mode, 2)
        total = (total + p(3));
    end
    if asils.models.sensorpower.sensor_on(mode, 3)
        total = (total + p(4));
    end
    if asils.models.sensorpower.sensor_on(mode, 4)
        total = (total + p(5));
    end
    if asils.models.sensorpower.sensor_on(mode, 5)
        total = (total + p(6));
    end
    if asils.models.sensorpower.sensor_on(mode, 6)
        total = (total + p(7));
    end
end
